{"title": "出错测试画布", "note": "三种错误各一个按钮", "html": "<style>
  .row{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}
  button{font:inherit;font-size:var(--font-text-sm-size);color:var(--color-text-primary);background:var(--color-background-primary);border:1px solid var(--color-border-secondary);border-radius:var(--border-radius-sm);padding:4px 12px;cursor:pointer}
  #log{font-size:var(--font-text-sm-size);color:var(--color-text-secondary)}
</style>
<div class="row">
  <button id="script-error" type="button">脚本报错</button>
  <button id="rejection" type="button">未处理的 rejection</button>
  <button id="csp" type="button">CSP 违规</button>
</div>
<div id="log">点一个按钮试试。</div>
<script>
  document.getElementById('script-error').addEventListener('click', function () {
    setTimeout(function () { throw new Error('t015 boom'); }, 0);
  });
  document.getElementById('rejection').addEventListener('click', function () {
    Promise.reject(new Error('t015 rejected'));
  });
  document.getElementById('csp').addEventListener('click', function () {
    fetch('https://off-list.example/t015').catch(function () {});
  });
</script>"}

